void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord.xy/iResolution.xy; // normalized pixel coordinates (from 0 to 1)
    uv -= 0.5; // centers uv
    uv.x *= iResolution.x/iResolution.y; // scales uv correctly

    vec3 col = vec3(0);
    float cell_size = .4;
    vec2 gv = fract(uv/cell_size)-.5; // grid uv
    float d = length(gv);
    float circle_radius = 1.5*(sin(iTime/15.)+1.4);
    float m = smoothstep(circle_radius, circle_radius-.1, d);
    float n = 0.; // counts how many circles are overlapping

    float max_offset = floor(2.*circle_radius/cell_size + 1.);
    for (float i=-max_offset; i<max_offset; i++) {
        for (float j=-max_offset; j<max_offset; j++) {
            d = length(gv + vec2(i,j));
            n += step(.1, smoothstep(circle_radius, circle_radius-.1, d));
        }
    }
    //col.rg = gv;
    col += m*mod(n, 2.);

    fragColor = vec4(col, 1.0);
}
